// tests/file-download-binary.test.ts - v1.2.5 FILE-DOWNLOAD-BINARY
// 新版 vendor DownloadFileBinary 完整下载 v1 schema 文件
// 覆盖: isV1SchemaFile 提取 download_context / enrichFileMessageFromV1Binary 下载+OSS

import { test } from "node:test";
import assert from "node:assert/strict";

import { isV1SchemaFile, enrichFileMessageFromV1Binary } from "../src/inbound/media-enrich.js";
import type { WppAccountCtx } from "../src/send/factory.js";

// ===== isV1SchemaFile 提取 download_context =====

test("v1.2.5 — isV1SchemaFile 提取新版 download_context", () => {
  const raw = {
    kind: "app",
    app: { category: "file", title: "报告.pdf", file_extension: "pdf" },
    file: {
      download_context: {
        attach_id: "@cdn_xxx",
        user_name: "wxid_dbdmq8riblxo12",
        data_len: 129583,
        endpoint: "/api/Tools/DownloadFileBinary",
        section: { start_pos: 0, data_len: 129583 },
      },
    },
  };
  const r = isV1SchemaFile(raw);
  assert.equal(r.isV1, true);
  assert.equal(r.filename, "报告.pdf");
  assert.equal(r.ext, "pdf");
  assert.ok(r.downloadCtx, "应提取 download_context");
  assert.equal(r.downloadCtx!.attachId, "@cdn_xxx");
  assert.equal(r.downloadCtx!.userName, "wxid_dbdmq8riblxo12");
  assert.equal(r.downloadCtx!.dataLen, 129583);
});

test("v1.2.5 — isV1SchemaFile 无 download_context (旧版推送) 不报错", () => {
  const raw = {
    kind: "app",
    app: { category: "file", title: "旧文件.pdf", file_extension: "pdf" },
  };
  const r = isV1SchemaFile(raw);
  assert.equal(r.isV1, true);
  assert.equal(r.filename, "旧文件.pdf");
  assert.equal(r.downloadCtx, undefined, "旧推送无 download_context");
});

test("v1.2.5 — isV1SchemaFile 非文件消息返回 false", () => {
  assert.equal(isV1SchemaFile({ kind: "text" }).isV1, false);
  assert.equal(isV1SchemaFile(null).isV1, false);
});

// ===== enrichFileMessageFromV1Binary =====

test("v1.2.5 — enrichFileMessageFromV1Binary 缺 attach_id 返回错误", async () => {
  const ctx: WppAccountCtx = { baseUrl: "http://test", tokenKey: "tk", authcode: "ac", accountId: "default" };
  const r = await enrichFileMessageFromV1Binary(
    ctx,
    { attachId: "", userName: "u", dataLen: 100 },
    "a.pdf",
    "pdf",
  );
  assert.equal(r.mediaUrl, null);
  assert.ok(r.error, "缺 attach_id 应报错");
});

// ===== v1.2.5 IMAGE-CDN: isV1SchemaImage 提取 cdn_download_contexts =====
import { isV1SchemaImage } from "../src/inbound/media-enrich.js";

test("v1.2.5 IMAGE-CDN — isV1SchemaImage 提取 standard 变体 cdn_download_contexts", () => {
  const raw = {
    kind: "image",
    local_id: 1357416805,
    conversation_id: "57737516566@chatroom",
    recipient_id: "q139198824",
    image: {
      aes_key: "f4458f103581036190d1fb0c077df0b0",
      cdn_download_contexts: [
        { endpoint: "/api/Tools/CdnDownloadImage", file_aes_key: "f4458f103581036190d1fb0c077df0b0", file_no: "cdn_standard_xxx", variant: "standard" },
        { endpoint: "/api/Tools/CdnDownloadImage", file_aes_key: "f4458f103581036190d1fb0c077df0b0", file_no: "cdn_thumb_xxx", variant: "thumbnail" },
      ],
      md5: "739234c72fa65e1a6997a6bd7f09ccc0",
    },
  };
  const r = isV1SchemaImage(raw);
  assert.equal(r.isV1, true);
  assert.equal(r.localId, 1357416805);
  assert.equal(r.toWxid, "57737516566@chatroom");
  assert.ok(r.cdnDownloadCtx, "应提取 cdn_download_contexts");
  assert.equal(r.cdnDownloadCtx!.fileNo, "cdn_standard_xxx", "应优先 standard 变体");
  assert.equal(r.md5, "739234c72fa65e1a6997a6bd7f09ccc0");
});

test("v1.2.5 IMAGE-CDN — isV1SchemaImage 无 cdn_download_contexts 不报错", () => {
  const raw = { kind: "image", local_id: 123, conversation_id: "g@chatroom", recipient_id: "bot" };
  const r = isV1SchemaImage(raw);
  assert.equal(r.isV1, true);
  assert.equal(r.cdnDownloadCtx, undefined, "旧推送无 cdn_download_contexts");
});

// ===== v1.2.6 VOICE-DOWNLOAD-BINARY: isV1SchemaVoice 提取 download_context =====
import { isV1SchemaVoice } from "../src/inbound/media-enrich.js";

test("v1.2.6 VOICE — isV1SchemaVoice 提取新版 voice.download_context", () => {
  const raw = {
    kind: "voice",
    type: 34,
    local_id: 1660506587,
    voice: {
      download_context: {
        chat_room_name: "57737516566@chatroom",
        client_msg_id: "client-123",
        format: 4,
        from_user_name: "57737516566@chatroom",
        length: 4206,
        master_buf_id: "0",
        msg_id: 1660506587,
        new_msg_id: "1346019200999807490",
        to_user_name: "q139198824",
      },
    },
  };
  const r = isV1SchemaVoice(raw);
  assert.equal(r.isV1, true);
  assert.equal(r.voiceCtx!.msgId, 1660506587);
  assert.equal(r.voiceCtx!.newMsgId, "1346019200999807490");
  assert.equal(r.voiceCtx!.clientMsgId, "client-123");
  assert.equal(r.voiceCtx!.chatRoomName, "57737516566@chatroom");
  assert.equal(r.voiceCtx!.format, 4);
});

test("v1.2.6 VOICE — isV1SchemaVoice 非语音/无 download_context 返回 false", () => {
  assert.equal(isV1SchemaVoice({ kind: "text" }).isV1, false);
  assert.equal(isV1SchemaVoice({ kind: "voice" }).isV1, false, "无 download_context");
  assert.equal(isV1SchemaVoice(null).isV1, false);
});

// src/inbound/media-enrich.ts - 媒体消息 enrich (下载 + OSS 上传 + 公网 URL)
// 双 schema 支持:
//   v0: content 含完整 XML (aeskey + cdn url) → /Tools/CdnDownloadImage 完整大图
//   v1: content = "收到一张图片" 总结, 无 XML → /Tools/DownloadImg + local_id, 但 vendor 单次硬限 64KB
// 凭据:
//   - OSS: ~/.openclaw/credentials/oss-credentials.json
//   - vendor: ctx (WppAccountCtx: baseUrl/tokenKey/authcode)
//
// v1.3.26 (2026-08-10, P3-2): 978 行按职责拆分到 media-enrich/ (shared/xml/image/file/voice/video),
//   本文件退化为薄 barrel re-export, 外部 import "./media-enrich.js" 契约不变.

export * from "./media-enrich/index.js";

// src/inbound/media-enrich/index.ts - 双层 barrel (v1.3.26 拆分, 2026-08-10 P3-2)
// 外部入口 media-enrich.ts re-export 本文件; 显式列出公共符号, 不泄漏 shared 内部 helper
// 注意: interface 是 type-only, 必须用 `export type {}` (否则运行时 ESM 报 no export)

// ===== 值导出 (函数) =====
export { parseImageXml, parseFileXml, parseVideoXml, parseVoiceXml } from "./xml.js";
export { enrichImageMessage, enrichImageMessageFromV1, enrichImageMessageFromV1Cdn, isV1SchemaImage } from "./image.js";
export { isV1SchemaFile, enrichFileMessage, enrichFileMessageFromV1Binary, enrichFileMessageViaMcp } from "./file.js";
export { isV1SchemaVoice, enrichVoiceMessage, enrichVoiceMessageFromV1 } from "./voice.js";
export { isV1SchemaVideo, enrichVideoMessage, enrichVideoMessageFromV1 } from "./video.js";

// ===== 类型导出 (interface, type-only) =====
export type { ImageEnrichResult, V1ImageCdnCtx } from "./image.js";
export type { V1FileDownloadCtx, FileEnrichResult } from "./file.js";
export type { MediaEnrichResult } from "./shared.js";
export type { V1VoiceDownloadCtx } from "./voice.js";
export type { V1VideoDownloadCtx } from "./video.js";

// src/inbound/media-enrich/xml.ts - 媒体消息 XML 解析器 (v0 schema)
// 从 media-enrich.ts v1.3.26 拆分 (2026-08-10, P3-2): 仅搬运, 不优化



/**
 * 从图片 XML 提取 CDN 下载参数 (aeskey + cdnthumburl/cdnbigimgurl)
 */
export function parseImageXml(xml: string): {
  aesKey: string;
  fileNo: string;
  md5?: string;
} | null {
  const aesKey = xml.match(/aeskey="([^"]+)"/)?.[1];
  const fileNo =
    xml.match(/cdnbigimgurl="([^"]+)"/)?.[1] ||
    xml.match(/cdnmidimgurl="([^"]+)"/)?.[1] ||
    xml.match(/cdnthumburl="([^"]+)"/)?.[1];
  const md5 = xml.match(/md5="([^"]+)"/)?.[1];
  if (!aesKey || !fileNo) return null;
  return { aesKey, fileNo, md5 };
}
/**
 * 解析 file msg XML → 拿 aeskey + fileNo + filename + size
 * vendor file XML 范式: <appmsg><type>6</type><appattach>
 *   <attachurl> <aeskey> <fileno> <fileext> <filename name="...">
 */
export function parseFileXml(xml: string): {
  aesKey: string;
  fileNo: string;
  filename: string;
  fileext: string;
  size?: number;
} | null {
  const aesKey = xml.match(/aeskey="([^"]+)"/)?.[1];
  // fileNo 字段名 vendor 多种: fileno / attachfileid / fileid / fileNo
  const fileNo =
    xml.match(/<fileno>([^<]+)<\/fileno>/)?.[1] ||
    xml.match(/fileno="([^"]+)"/)?.[1] ||
    xml.match(/<attachfileid>([^<]+)<\/attachfileid>/)?.[1] ||
    xml.match(/fileid="([^"]+)"/)?.[1] ||
    xml.match(/fileNo="([^"]+)"/)?.[1];
  const filenameRaw = xml.match(/<filename[^>]*>([^<]+)<\/filename>/)?.[1] || "file";
  const filename = filenameRaw.replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
  const fileext = xml.match(/<fileext>([^<]+)<\/fileext>/)?.[1] || filename.split(".").pop() || "bin";
  const sizeStr = xml.match(/<totallen>([^<]+)<\/totallen>/)?.[1];
  const size = sizeStr ? parseInt(sizeStr, 10) : undefined;
  if (!aesKey || !fileNo) return null;
  return { aesKey, fileNo, filename, fileext, size };
}
/**
 * 解析 videomsg XML → aeskey + cdnthumbaeskey/cdnthumburl/cdnvideourl
 * 注: 微信 videomsg 有两个 CDN: 视频本体 + 缩略图
 */
export function parseVideoXml(xml: string): {
  aesKey: string;
  fileNo: string;
  md5?: string;
  thumbUrl?: string;
  playLength?: number;
} | null {
  const aesKey = xml.match(/aeskey="([^"]+)"/)?.[1];
  // videomsg 通常用 cdnvideourl/cdnvideourl/aeskey 字段
  const fileNo =
    xml.match(/cdnvideourl="([^"]+)"/)?.[1] ||
    xml.match(/<cdnvideourl>([^<]+)<\/cdnvideourl>/)?.[1] ||
    xml.match(/cdnvideofileid="([^"]+)"/)?.[1] ||
    xml.match(/fileid="([^"]+)"/)?.[1];
  const md5 = xml.match(/md5="([^"]+)"/)?.[1] || xml.match(/<md5>([^<]+)<\/md5>/)?.[1];
  const thumbUrl = xml.match(/cdnthumbaeskey="([^"]+)"/)?.[1];
  const playLengthStr = xml.match(/<playlength>([^<]+)<\/playlength>/)?.[1];
  const playLength = playLengthStr ? parseInt(playLengthStr, 10) : undefined;
  if (!aesKey || !fileNo) return null;
  return { aesKey, fileNo, md5, thumbUrl, playLength };
}
/**
 * 解析 voicemsg XML → aeskey + fileNo (silk/AMR/MP3)
 */
export function parseVoiceXml(xml: string): {
  aesKey: string;
  fileNo: string;
  md5?: string;
  durationMs?: number;
} | null {
  const aesKey = xml.match(/aeskey="([^"]+)"/)?.[1];
  const fileNo =
    xml.match(/cdnvoiceurl="([^"]+)"/)?.[1] ||
    xml.match(/<voicelength>([^<]+)<\/voicelength>/)?.[1] && xml.match(/voiceurl="([^"]+)"/)?.[1] ||
    xml.match(/fileid="([^"]+)"/)?.[1];
  const md5 = xml.match(/md5="([^"]+)"/)?.[1] || xml.match(/<md5>([^<]+)<\/md5>/)?.[1];
  const durationStr = xml.match(/<voicelength>([^<]+)<\/voicelength>/)?.[1];
  const durationMs = durationStr ? parseInt(durationStr, 10) : undefined;
  if (!aesKey || !fileNo) return null;
  return { aesKey, fileNo, md5, durationMs };
}

// src/inbound/media-enrich/image.ts - 图片消息 enrich (v0 XML + v1 schema + v1 CDN 完整大图)
// 从 media-enrich.ts v1.3.26 拆分 (2026-08-10, P3-2): 仅搬运, 不优化

import { logObj as log, formatErr } from "../../core/logger.js";
import { parseImageXml } from "./xml.js";
import { loadOssConfig, uploadToOss, downloadImageBase64, buildOssKey, sanitizeFilenamePart } from "./shared.js";
import type { WppAccountCtx } from "../../send/factory.js";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";

export interface ImageEnrichResult {
  mediaUrl: string | null;
  mediaSize: number | null;
  error?: string;
}
/**
 * 图片消息 enrich 主入口: 下载 → OSS 上传 → 公网 URL。
 * 任何失败都吞错返回 { mediaUrl: null } (不阻塞消息处理), 只 log warn。
 */
export async function enrichImageMessage(
  ctx: WppAccountCtx,
  xml: string,
): Promise<ImageEnrichResult> {
  const parsed = parseImageXml(xml);
  if (!parsed) {
    return { mediaUrl: null, mediaSize: null, error: "no aeskey/fileNo in xml" };
  }
  const oss = loadOssConfig();
  if (!oss) {
    return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  }
  let tmpPath: string | null = null;
  try {
    const b64 = await downloadImageBase64(ctx, parsed.aesKey, parsed.fileNo);
    const img = Buffer.from(b64, "base64");
    tmpPath = path.join(
      os.tmpdir(),
      `wpp-img-${crypto.randomBytes(6).toString("hex")}.jpg`,
    );
    fs.writeFileSync(tmpPath, img);
    const filename = `${sanitizeFilenamePart(parsed.md5)}.jpg`;
    const ossKey = buildOssKey(ctx.accountId, "images", filename);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.3.74] image enrich OSS: ${url} (${img.length} bytes)`);
    return { mediaUrl: url, mediaSize: img.length };
  } catch (e) {
    log.warn(`[WPP v1.3.74] image enrich failed: ${formatErr(e)}`, {
      aesKey: parsed.aesKey,
    });
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) {
      try {
        fs.unlinkSync(tmpPath);
      } catch {
        /* ignore */
      }
    }
  }
}
/**
 * v1 schema 图片 enrich: raw_payload kind=image, content="收到一张图片", 无 aeskey/cdnbigimgurl
 * 用 /Tools/DownloadImg {msgId: local_id, toWxid} → 首 64KB JPEG (vendor 硬限) → ossutil → 公网 URL
 *
 * @param ctx WppAccountCtx (含 vendor 凭证)
 * @param localId v1 schema 推送的 local_id (uint32, 实际是 vendor 内部 msgId)
 * @param toWxid 接收方 wxid (私聊=bot 自己, 群聊=群 ID)
 * @param md5 可选, 用于 OSS key 命名 (避免重复); 缺失时用 localId 哈希
 */
export async function enrichImageMessageFromV1(
  ctx: WppAccountCtx,
  localId: number,
  toWxid: string,
  md5?: string,
  dataLen?: number,
): Promise<ImageEnrichResult> {
  if (!Number.isInteger(localId) || localId <= 0 || localId > 0xffffffff) {
    return { mediaUrl: null, mediaSize: null, error: `invalid localId: ${localId}` };
  }
  const oss = loadOssConfig();
  if (!oss) {
    return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  }
  let tmpPath: string | null = null;
  try {
    const { postWppJson } = await import("../../api/client.js");
    const { ctxToCallOpts } = await import("../../send/factory.js");
    const resp = await postWppJson<{
      data?: { buffer: string; iLen?: number };
      totalLen?: number;
      BaseResponse?: { ret?: number; errMsg?: { string?: string } };
    }>(
      ctx.baseUrl,
      "/Tools/DownloadImg",
      // v1.3.70: 新 vendor DownloadImg 必填 snake_case (msg_id/to_wxid/data_len) + section; 旧字段 msgId/toWxid 报 INVALID_ARGUMENT
      {
        msg_id: localId,
        to_wxid: toWxid,
        data_len: dataLen ?? 0,
        compress_type: 0,
        ...(dataLen ? { section: { start_pos: 0, data_len: dataLen } } : {}),
      },
      { ...ctxToCallOpts(ctx), timeoutMs: 30000, maxRetries: 1 },
    );
    const baseRet = resp.Data?.BaseResponse?.ret;
    if (resp.Code !== 0 || baseRet !== 0) {
      const errMsg = resp.Data?.BaseResponse?.errMsg?.string ?? `Code=${resp.Code}`;
      return { mediaUrl: null, mediaSize: null, error: `vendor ret: ${errMsg}` };
    }
    const buf = resp.Data?.data?.buffer;
    if (!buf) {
      return { mediaUrl: null, mediaSize: null, error: "vendor no data.buffer" };
    }
    const img = Buffer.from(buf, "base64");
    if (img.length < 100 || img[0] !== 0xff || img[1] !== 0xd8) {
      return { mediaUrl: null, mediaSize: null, error: `not a valid JPEG (len=${img.length}, head=${img.slice(0, 4).toString("hex")})` };
    }
    tmpPath = path.join(
      os.tmpdir(),
      `wpp-v1-img-${crypto.randomBytes(6).toString("hex")}.jpg`,
    );
    fs.writeFileSync(tmpPath, img);
    const filename = `${sanitizeFilenamePart(md5)}-${localId}.jpg`;
    const ossKey = buildOssKey(ctx.accountId, "images", filename);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    log.info(
      `[WPP v1.2.0 V1-SCHEMA-ENRICH] image enrich (v1 schema) ok: localId=${localId} url=${url} (${img.length} bytes, vendor 64KB cap)`,
    );
    return { mediaUrl: url, mediaSize: img.length };
  } catch (e) {
    log.warn(`[WPP v1.3.74] v1 schema image enrich failed: ${formatErr(e)}`, { localId });
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) {
      try {
        fs.unlinkSync(tmpPath);
      } catch {
        /* ignore */
      }
    }
  }
}
/**
 * v1.2.5 IMAGE-CDN-DOWNLOAD: 用新版 cdn_download_contexts 走 CdnDownloadImage 完整下载大图。
 * 新版 vendor (8/10) 推送 image.cdn_download_contexts (file_aes_key + file_no),
 * CdnDownloadImage 返回**完整大图** (非旧 DownloadImg 的 64KB 截断)。
 * 失败降级 → 返回 error (调用方 fallback 到 DownloadImg 64KB 或标注失败)。
 */
export async function enrichImageMessageFromV1Cdn(
  ctx: WppAccountCtx,
  cdnCtx: V1ImageCdnCtx,
  md5?: string,
): Promise<ImageEnrichResult> {
  if (!cdnCtx.fileAesKey || !cdnCtx.fileNo) {
    return { mediaUrl: null, mediaSize: null, error: "no file_aes_key/file_no in cdn_download_contexts" };
  }
  const oss = loadOssConfig();
  if (!oss) {
    return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  }
  let tmpPath: string | null = null;
  try {
    const b64 = await downloadImageBase64(ctx, cdnCtx.fileAesKey, cdnCtx.fileNo);
    const img = Buffer.from(b64, "base64");
    if (img.length < 100 || img[0] !== 0xff || img[1] !== 0xd8) {
      return { mediaUrl: null, mediaSize: null, error: `not a valid JPEG (len=${img.length})` };
    }
    tmpPath = path.join(os.tmpdir(), `wpp-v1-img-cdn-${crypto.randomBytes(6).toString("hex")}.jpg`);
    fs.writeFileSync(tmpPath, img);
    const filename = `${sanitizeFilenamePart(md5)}.jpg`;
    const ossKey = buildOssKey(ctx.accountId, "images", filename);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.2.5 IMAGE-CDN-DOWNLOAD] ok: ${url} (${img.length} bytes, variant=${cdnCtx.variant ?? "?"})`);
    return { mediaUrl: url, mediaSize: img.length };
  } catch (e) {
    log.warn(`[WPP v1.2.5 IMAGE-CDN-DOWNLOAD] failed: ${formatErr(e)}`, { fileNo: cdnCtx.fileNo.slice(0, 20) });
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) {
      try {
        fs.unlinkSync(tmpPath);
      } catch {
        /* ignore */
      }
    }
  }
}
/**
 * v1.2.5: 图片 CDN 下载凭证 (新版 vendor 8/10 推送: image.cdn_download_contexts)
 * 结构: [{ endpoint, file_aes_key, file_no, variant: "standard"|"thumbnail" }]
 */
export interface V1ImageCdnCtx {
  fileAesKey: string;
  fileNo: string;
  variant?: string;
}
/**
 * 判定 v1 schema 图片 (raw_payload kind=image + local_id, 无 v0 Content/ImgBuf)
 * v1.2.5: 新版推送带 image.cdn_download_contexts → 可走 CdnDownloadImage 完整大图 (非 64KB 截断)
 */
export function isV1SchemaImage(raw: unknown): {
  isV1: boolean;
  localId?: number;
  md5?: string;
  toWxid?: string;
  dataLen?: number;
  cdnDownloadCtx?: V1ImageCdnCtx;
} {
  if (!raw || typeof raw !== "object") return { isV1: false };
  const r = raw as Record<string, unknown>;
  // v1 schema 特征: kind === "image" + local_id (uint32 数字) + 无 v0 字段 (Content/ImgBuf)
  if (r.kind === "image" && typeof r.local_id === "number" && r.local_id > 0) {
    const isV1 = !("Content" in r) && !("ImgBuf" in r);
    if (!isV1) return { isV1: false };
    // 群聊用 conversation_id (群 ID), 私聊用 recipient_id (bot 自己)
    const toWxid =
      typeof r.conversation_id === "string" && r.conversation_id.endsWith("@chatroom")
        ? r.conversation_id
        : typeof r.recipient_id === "string"
        ? r.recipient_id
        : undefined;

    let cdnDownloadCtx: V1ImageCdnCtx | undefined;
    const imageObj = r.image as Record<string, unknown> | undefined;
    const cdnCtxs = imageObj?.cdn_download_contexts;
    if (Array.isArray(cdnCtxs)) {
      const standard = cdnCtxs.find(
        (c) => (c as Record<string, unknown>).variant === "standard",
      ) as Record<string, unknown> | undefined;
      const pick = standard ?? (cdnCtxs[0] as Record<string, unknown> | undefined);
      if (pick && typeof pick.file_aes_key === "string" && typeof pick.file_no === "string") {
        cdnDownloadCtx = {
          fileAesKey: pick.file_aes_key,
          fileNo: pick.file_no,
          variant: typeof pick.variant === "string" ? pick.variant : undefined,
        };
      }
    }

    return {
      isV1: true,
      localId: r.local_id as number,
      md5: typeof imageObj?.md5 === "string" ? imageObj.md5 : undefined,
      toWxid,
      // v1.3.70: 提取图片字节数 (新 vendor DownloadImg 必填 data_len) — image 对象或顶层 data_len/total_len
      dataLen:
        typeof imageObj?.data_len === "number"
          ? imageObj.data_len
          : typeof imageObj?.total_len === "number"
          ? imageObj.total_len
          : typeof imageObj?.file_size === "number"
          ? imageObj.file_size
          : typeof r.data_len === "number"
          ? r.data_len
          : undefined,
      cdnDownloadCtx,
    };
  }
  return { isV1: false };
}

// core/logger.ts - 仿 pino 接口日志 (兼容现有 log.info 调用 + 新代码函数式 info/warn/error)
// 范式仿 本项目/src/core/logger.ts
// 关键: formatErr 自动保留 stack (silent killer 永久救回)

import { PLUGIN_VERSION } from "./constants.js";

const LOG_TAG = `[WPP v${PLUGIN_VERSION}]`;

/**
 * formatErr — Error 实例保留 stack; 非 Error 实例走 String()
 * silent killer 永久救回: 之前 18+ 处只打 e.message 漏 stack, prod 难定位
 */
export function formatErr(err: unknown): string {
  if (err instanceof Error) {
    if (err.stack) return `${err.name}: ${err.message}\n${err.stack}`;
    return `${err.name}: ${err.message}`;
  }
  if (err === null || err === undefined) return String(err);
  if (typeof err === "string") return err;
  try {
    return JSON.stringify(err);
  } catch {
    return String(err);
  }
}

type Level = "INFO" | "WARN" | "ERROR" | "DEBUG";
type Fields = Record<string, unknown>;

function fmtValue(v: unknown): string {
  if (typeof v === "string") {
    return /[\s,=]/.test(v) ? JSON.stringify(v) : v;
  }
  if (v === null || v === undefined) return String(v);
  if (typeof v === "number" || typeof v === "boolean") return String(v);
  if (v instanceof Error) {
    return `"${formatErr(v).replace(/"/g, '\\"').replace(/\n/g, "\\n")}"`;
  }
  try {
    return JSON.stringify(v) ?? "null";
  } catch {
    return String(v);
  }
}

function fmtFields(fields?: Fields): string {
  if (!fields) return "";
  const parts: string[] = [];
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined) continue;
    parts.push(`${k}=${fmtValue(v)}`);
  }
  return parts.length ? " " + parts.join(" ") : "";
}

function emit(level: Level, msg: string, fields?: Fields): void {
  const line = `${new Date().toISOString()} ${level} ${LOG_TAG} ${msg}${fmtFields(fields)}`;
  if (level === "ERROR") console.error(line);
  else if (level === "WARN") console.warn(line);
  // eslint-disable-next-line no-console -- 中心 logger INFO/DEBUG 必需
  else console.log(line);
}

/**
 * Normalize fields-or-error arg into Fields record.
 * Error instances → { err: "<formatErr>" }, primitives → { value: v }
 */
function normalize(arg: unknown): Fields | undefined {
  if (arg === undefined) return undefined;
  if (arg instanceof Error) return { err: formatErr(arg) };
  if (typeof arg === "object" && arg !== null) return arg as Fields;
  return { value: arg };
}

// ============ 函数式 (本项目 风格 — 新代码推荐) ============

export function info(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("INFO", msg, normalize(fieldsOrErr));
}

export function warn(msg: string, fieldsOrErr?: Fields | unknown): void {
  emit("WARN", msg, normalize(fieldsOrErr));
}

export function error(msg: string, err?: unknown): void {
  emit("ERROR", msg, normalize(err));
}

export function debug(msg: string, fields?: Fields): void {
  if (process.env.WPP_DEBUG !== "1") return;
  emit("DEBUG", msg, fields);
}

// ============ 对象式 (兼容现有 log.info/warn/error/debug 调用) ============

function objectStyle(level: Level) {
  return (msg: string, fieldsOrErr?: Fields | unknown) => {
    emit(level, msg, normalize(fieldsOrErr));
  };
}

export const logObj = {
  info: objectStyle("INFO"),
  warn: objectStyle("WARN"),
  error: objectStyle("ERROR"),
  debug: objectStyle("DEBUG"),
} as const;

/** 默认 export = logObj 对象 (兼容 `import log from ...; log.info(...)`) */
export default logObj;

