/**
 * v1 schema 文件的下载凭证 (新版 vendor 8/10 推送: file.download_context)
 * download_context 结构: { attach_id, user_name, data_len, endpoint, section:{start_pos, data_len} }
 */
export interface V1FileDownloadCtx {
  attachId: string;
  userName: string;
  dataLen: number;
  endpoint?: string;
}
/**
 * 判定 v1 schema 文件 (raw_payload kind=app, app.category=file)
 * v1.2.5: 新版 vendor 推送带 file.download_context → 可完整下载 (DownloadFileBinary)
 */
export function isV1SchemaFile(raw: unknown): {
  isV1: boolean;
  filename?: string;
  ext?: string;
  downloadCtx?: V1FileDownloadCtx;
} {
  if (!raw || typeof raw !== "object") return { isV1: false };
  const r = raw as Record<string, unknown>;
  // v1 schema 特征: kind === "app" + app.category === "file"
  if (r.kind === "app" && typeof r.app === "object" && r.app !== null) {
    const app = r.app as Record<string, unknown>;
    if (app.category === "file") {
      // 新版: file.download_context (完整下载凭证)
      let downloadCtx: V1FileDownloadCtx | undefined;
      const fileObj = r.file as Record<string, unknown> | undefined;
      const dc = fileObj?.download_context as Record<string, unknown> | undefined;
      if (dc && typeof dc.attach_id === "string") {
        downloadCtx = {
          attachId: dc.attach_id,
          userName: typeof dc.user_name === "string" ? dc.user_name : "",
          dataLen: typeof dc.data_len === "number" ? dc.data_len : 0,
          endpoint: typeof dc.endpoint === "string" ? dc.endpoint : undefined,
        };
      }
      return {
        isV1: true,
        filename: typeof app.title === "string" ? app.title : undefined,
        ext: typeof app.file_extension === "string" ? app.file_extension : undefined,
        downloadCtx,
      };
    }
  }
  return { isV1: false };
}
/**
 * 文件 enrich: /Tools/DownloadFile → base64 → OSS → 公网 URL
 * 失败 fallback: 标注文件名 + 大小, AI 知道有文件但无法下载
 */
export interface FileEnrichResult {
  mediaUrl: string | null;
  filename: string;
  size: number | null;
  error?: string;
}
export async function enrichFileMessage(
  ctx: WppAccountCtx,
  xml: string,
): Promise<FileEnrichResult> {
  const parsed = parseFileXml(xml);
  if (!parsed) return { mediaUrl: null, filename: "", size: null, error: "no aeskey/fileNo in xml" };
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, filename: parsed.filename, size: parsed.size ?? null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  try {
    const b64 = await downloadByEndpoint(ctx, "/Tools/DownloadFile", parsed.aesKey, parsed.fileNo);
    const buf = Buffer.from(b64, "base64");
    tmpPath = path.join(os.tmpdir(), `wpp-file-${crypto.randomBytes(6).toString("hex")}.${parsed.fileext}`);
    fs.writeFileSync(tmpPath, buf);
    const hash = crypto.createHash("md5").update(parsed.filename).digest("hex").slice(0, 12);
    const safeName = parsed.filename.replace(/[^\w.\-]/g, "_");
    const ossKey = buildOssKey(ctx.accountId, "files", `${hash}-${safeName}`);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.3.74] file enrich OSS: ${url} (${buf.length} bytes, ${parsed.filename})`);
    return { mediaUrl: url, filename: parsed.filename, size: buf.length };
  } catch (e) {
    log.warn(`[WPP v1.3.74] file enrich failed: ${formatErr(e)}`, { filename: parsed.filename });
    return { mediaUrl: null, filename: parsed.filename, size: parsed.size ?? null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
/**
 * v1.2.5 FILE-DOWNLOAD-BINARY: 用新版 DownloadFileBinary 完整下载 v1 schema 文件。
 * 新版 vendor (8/10) 推送 file.download_context (attach_id/user_name/data_len), 直接提交
 * 即可让服务端自动拉全部分片 → 返回原始文件字节流 → 上传 OSS → 公网 URL。
 *
 * 调用方式 (实测):
 *   POST {baseUrl}/api/Tools/DownloadFileBinary?authcode=<authcode>   ← authcode 必须走 query!
 *   Header: TokenKey: <tokenKey>
 *   Body: { attach_id, user_name, data_len, section: {start_pos, data_len} }
 *   返回: 原始文件字节 (Content-Disposition 附件, 不经 Base64)
 */
export async function enrichFileMessageFromV1Binary(
  ctx: WppAccountCtx,
  downloadCtx: V1FileDownloadCtx,
  filename: string,
  ext: string,
): Promise<FileEnrichResult> {
  if (!downloadCtx.attachId) {
    return { mediaUrl: null, filename, size: null, error: "no attach_id in download_context" };
  }
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, filename, size: null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  try {
    //   原本裸 fetch + 整文件进 Buffer, 恶意 vendor 推送可 OOM
    const url = `${ctx.baseUrl.replace(/\/$/, "")}/api/Tools/DownloadFileBinary?authcode=${encodeURIComponent(ctx.authcode ?? "")}`;
    const buf = await safeFetchWithCap(
      url,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "TokenKey": ctx.tokenKey,
        },
        body: JSON.stringify({
          attach_id: downloadCtx.attachId,
          user_name: downloadCtx.userName,
          data_len: downloadCtx.dataLen,
          section: { start_pos: 0, data_len: downloadCtx.dataLen },
        }),
        signal: AbortSignal.timeout(30_000),
      },
      100 * 1024 * 1024, // 100MB hard cap (file 通常 <50MB)
    );
    if (buf.length === 0 || buf.length < 10) {
      return { mediaUrl: null, filename, size: null, error: `DownloadFileBinary empty (${buf.length} bytes)` };
    }

    const safeExt = ext ? ext.replace(/[^\w]/g, "").toLowerCase() : "bin";
    tmpPath = path.join(os.tmpdir(), `wpp-file-v1-${crypto.randomBytes(6).toString("hex")}.${safeExt}`);
    fs.writeFileSync(tmpPath, buf);

    const hash = crypto.createHash("md5").update(filename).digest("hex").slice(0, 12);
    const safeName = filename.replace(/[^\w.\-]/g, "_");
    const ossKey = buildOssKey(ctx.accountId, "files", `${hash}-${safeName}`);
    const ossUrl = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.2.5 FILE-DOWNLOAD-BINARY] download ok: ${filename} (${buf.length} bytes) → ${ossUrl}`);
    return { mediaUrl: ossUrl, filename, size: buf.length };
  } catch (e) {
    log.warn(`[WPP v1.2.5 FILE-DOWNLOAD-BINARY] download failed: ${formatErr(e)}`, { filename });
    return { mediaUrl: null, filename, size: null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
/**
 * v1.2.0 VENDOR-MCP: v1 schema 文件通过 vendor MCP 尝试下载
 * 流程: MCP wechat_get_recent_messages 拿完整 payload → 找 CDN URL → 下载 → OSS → 公网 URL
 * 失败 (MCP 不可用 / 无 CDN URL / 下载失败) → 返回 null, 调用方走确定性回复兜底
 */
export async function enrichFileMessageViaMcp(
  localId: number,
  filename: string,
  accountId?: string,
): Promise<FileEnrichResult> {
  const { resolveFileViaMcp: mcpResolve } = await import("../../vendor-mcp-client.js");
  // v1.3.60 MULTI-ACCOUNT: 传 accountId → MCP 用对应账号 token
  const resolved = await mcpResolve(localId, filename, accountId);
  if (!resolved?.cdnUrl) {
    return { mediaUrl: null, filename, size: null, error: "mcp no cdn url" };
  }
  // 2. 下载 CDN URL (v1.2.1 P2-fix: 抽 ossUploadBuffer 复用上传逻辑)
  try {
    const buf = await safeFetchWithCap(resolved.cdnUrl, { signal: AbortSignal.timeout(30_000) }, 100 * 1024 * 1024);
    if (buf.length === 0) return { mediaUrl: null, filename, size: null, error: "cdn empty body" };
    const url = await ossUploadBuffer(buf, filename, "wpp/mcp-files");
    log.info(`[WPP v1.2.0 VENDOR-MCP] file enrich via MCP OSS: ${url} (${buf.length} bytes, ${filename})`);
    return { mediaUrl: url, filename, size: buf.length };
  } catch (e) {
    log.warn(`[WPP v1.2.0 VENDOR-MCP] file enrich via MCP failed: ${formatErr(e)}`, { filename });
    return { mediaUrl: null, filename, size: null, error: (e as Error).message };
  }
}

// src/util/safe-fetch.ts - v1.3.18 P1-安全2 + F1/F4/F5 fix (2026-08-10)
// 限制 fetch 只到白名单 host, 防 SSRF (prompt 注入 → 外带内网 / metadata / 本地 vendor)
// + 加字节 cap, 防 OOM (恶意/慢速 CDN → 内存耗尽)
//
// 设计:
//   - safeFetch: 只做 host 白名单 + 协议校验, 透传 vendor fetch
//   - safeFetchWithCap: 在 safeFetch 基础上加 maxBytes 限制 (Content-Length 预检 + 流式累加兜底)
//   - isHostAllowed: 暴露给测试, 也可由调用方自行判断 (e.g. 构造 URL 前)
//
// 白名单: OSS bucket + vendor 公网反代 (跟 enqueue/OSS 实际使用一致)
//   - openclaw-a.oss-cn-hangzhou.aliyuncs.com (OSS)
//   - wx.juhe.chat (vendor 反代, 即 API host)
//
// 阻止列表: loopback / 私网 / link-local (含 cloud metadata 169.254.169.254) / localhost / IPv6 loopback

import { URL } from "node:url";

/**
 * v1.3.19 RELEASE: vendor host 可经 env WPP_VENDOR_HOST 覆盖 (发布版不含默认域名, 接收方设自己 vendor host).
 * 生产不设 env → 默认 wx.juhe.chat (行为不变).
 * 用 function 动态读 env (避免 module load 时 env 未设).
 */
function getAllowedHosts(): Set<string> {
  const vendorHost = process.env.WPP_VENDOR_HOST || "wx.juhe.chat";
  return new Set([
    // OSS bucket
    "openclaw-a.oss-cn-hangzhou.aliyuncs.com",
    // vendor 公网反代 (可配置)
    vendorHost,
    // v1.3.27 P3-safe-fetch: 3 个第三方 AI 服务 (配置/常量来源, 非用户输入; 白名单化后
    //   裸 fetch → safeFetch, 仍拦截内网/loopback/metadata, 防 prompt 注入 → URL 操控)
    "dashscope.aliyuncs.com",     // 阿里 embedding (intent-embed)
    "api.minimaxi.com",           // MiniMax LLM (intent-llm)
    "api.siliconflow.cn",         // SiliconFlow STT (storage/stt)
  ]);
}

const BLOCKED_HOST_PATTERNS: RegExp[] = [
  /^127\./,                    // loopback (127.0.0.0/8)
  /^10\./,                     // private 10.0.0.0/8
  /^172\.(1[6-9]|2\d|3[01])\./, // private 172.16.0.0/12
  /^192\.168\./,               // private 192.168.0.0/16
  /^169\.254\./,               // link-local (含 cloud metadata 169.254.169.254)
  /^0\.0\.0\.0$/,
  /^::1$/,                     // IPv6 loopback
  /^fe80:/i,                   // IPv6 link-local
  /^localhost$/i,
];

/**
 * 判定 URL 是否在 host 白名单内 (协议 http/https + 非黑名单 + 在 ALLOWED_HOSTS 集合)
 * 默认拒绝: 不在白名单 → false
 */
export function isHostAllowed(url: string): boolean {
  let u: URL;
  try {
    u = new URL(url);
  } catch {
    return false;
  }
  // 协议白名单 (http/https only)
  if (!/^https?:$/.test(u.protocol)) return false;
  // 黑名单优先 (loosely match 私网 + metadata)
  if (BLOCKED_HOST_PATTERNS.some((p) => p.test(u.hostname))) return false;
  // 白名单 (唯一允许通过的 host, 动态读 env 支持发布版自定义)
  if (getAllowedHosts().has(u.hostname)) return true;
  return false; // 默认拒绝
}

/**
 * 带 host 白名单的 fetch (代替裸 fetch), 不在白名单 → throw.
 * 返回 Response, 调用方负责 .ok/.status/.body/.arrayBuffer() 等.
 */
export async function safeFetch(url: string, init?: RequestInit): Promise<Response> {
  if (!isHostAllowed(url)) {
    throw new Error(`safeFetch: host not in whitelist: ${url}`);
  }
  return fetch(url, init);
}

/**
 * v1.3.18 F1/F4/F5 fix: 媒体下载字节 cap (防恶意/慢速 CDN → OOM).
 * 默认 100MB hard cap (F1/F4/F5 防御).
 *
 * 流程:
 *   1. safeFetch 拉 response (host 白名单 + 超时透传)
 *   2. Content-Length 预检 → 超 cap 立刻 throw
 *   3. 流式 reader 累加 → 任何时刻超出 cap 立刻 cancel + throw
 *   4. 累加 chunks → Buffer.concat 返回
 */
export const MAX_MEDIA_BYTES = 100 * 1024 * 1024; // 100MB hard cap

/**
 * 带 host 白名单 + 字节 cap 的 fetch → 返回 Buffer.
 *
 * @param url 目标 URL (必须 isHostAllowed)
 * @param init fetch init (headers/signal/timeout)
 * @param maxBytes 字节 cap (默认 100MB, sendFile 用 50MB 更严)
 */
export async function safeFetchWithCap(
  url: string,
  init?: RequestInit,
  maxBytes: number = MAX_MEDIA_BYTES,
): Promise<Buffer> {
  const resp = await safeFetch(url, init);
  if (!resp.ok) throw new Error(`safeFetchWithCap: HTTP ${resp.status} (${url})`);
  // Content-Length 预检 (defense in depth)
  const contentLength = parseInt(resp.headers.get("content-length") ?? "0", 10);
  if (contentLength > maxBytes) {
    throw new Error(`safeFetchWithCap: Content-Length ${contentLength} > cap ${maxBytes} (${url})`);
  }
  // 流式累加 + cap 校验 (兜底: Content-Length 缺失/被伪造时仍能 catch)
  const reader = resp.body?.getReader();
  if (!reader) throw new Error(`safeFetchWithCap: no body reader (${url})`);
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel().catch(() => {/* ignore */});
        throw new Error(`safeFetchWithCap: stream exceeded cap ${maxBytes} bytes (${url})`);
      }
      chunks.push(value);
    }
  } catch (e) {
    // 确保 stream 被关闭 (避免 connection leak)
    await reader.cancel().catch(() => {/* ignore */});
    throw e;
  }
  // 拼 Buffer (length 精确)
  let len = 0;
  for (const c of chunks) len += c.byteLength;
  return Buffer.concat(chunks, len);
}

// src/inbound/media-enrich/voice.ts - 语音消息 enrich (v0 XML + v1 Binary + STT/vendor transcript)
// 从 media-enrich.ts v1.3.26 拆分 (2026-08-10, P3-2): 仅搬运, 不优化

import { logObj as log, formatErr } from "../../core/logger.js";
import { safeFetchWithCap } from "../../util/safe-fetch.js";
import { transcribeSilkBuffer } from "../../storage/stt.js";
import { parseVoiceXml } from "./xml.js";
import { loadOssConfig, uploadToOss, downloadByEndpoint, buildOssKey } from "./shared.js";
import type { MediaEnrichResult } from "./shared.js";
import type { WppAccountCtx } from "../../send/factory.js";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";

/** 语音消息 (msgType=34) 下载 + OSS + STT 转写 */
export async function enrichVoiceMessage(
  ctx: WppAccountCtx,
  xml: string,
): Promise<MediaEnrichResult> {
  const parsed = parseVoiceXml(xml);
  if (!parsed) return { mediaUrl: null, mediaSize: null, error: "no aeskey/fileNo in xml" };
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  let sttText: string | null = null;
  try {
    // vendor 端点无 Cdn 前缀 (错调 /Tools/CdnDownloadVoice 会 404)
    const b64 = await downloadByEndpoint(ctx, "/Tools/DownloadVoice", parsed.aesKey, parsed.fileNo);
    const buf = Buffer.from(b64, "base64");
    tmpPath = path.join(os.tmpdir(), `wpp-voice-${crypto.randomBytes(6).toString("hex")}.silk`);
    fs.writeFileSync(tmpPath, buf);
    const filename = `${parsed.md5 ?? crypto.randomBytes(8).toString("hex")}.silk`;
    const ossKey = buildOssKey(ctx.accountId, "voices", filename);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    // 下载完顺手 STT 转写 (siliconflow SenseVoiceSmall); 失败不阻塞
    try {
      const sttR = await transcribeSilkBuffer(buf);
      if (sttR?.text) {
        sttText = sttR.text;
        log.info(`[WPP v1.3.74] voice STT ok: text="${sttText.slice(0, 50)}${sttText.length > 50 ? "..." : ""}"`);
      }
    } catch (e) {
      log.warn(`[WPP v1.3.74] voice STT failed (non-fatal): ${formatErr(e)}`);
    }
    log.info(`[WPP v1.3.74] voice enrich OSS: ${url} (${buf.length} bytes, ${parsed.durationMs ?? "?"}ms)`);
    // 把 STT 文字拼到 MediaEnrichResult 让 handler 注入 content
    return { mediaUrl: url, mediaSize: buf.length, ...(sttText ? { filename: sttText } : {}) };
  } catch (e) {
    log.warn(`[WPP v1.3.74] voice enrich failed: ${formatErr(e)}`, { aesKey: parsed.aesKey });
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
/**
 * v1.2.6 VOICE-DOWNLOAD-BINARY: 新版 vendor (8/10) 语音推送带 voice.download_context,
 * 提交给 DownloadVoiceBinary → 返回 SILK/AMR/MP3/WAV 原始字节 → STT 转写 + OSS。
 */
export interface V1VoiceDownloadCtx {
  msgId: number;
  newMsgId: string;
  clientMsgId: string;
  masterBufId: string;
  format: number;
  length: number;
  chatRoomName?: string;
  fromUserName?: string;
  toUserName?: string;
}
/** 从 raw_payload 提取新版语音 download_context (kind=voice + voice.download_context) */
export function isV1SchemaVoice(raw: unknown): { isV1: boolean; voiceCtx?: V1VoiceDownloadCtx } {
  if (!raw || typeof raw !== "object") return { isV1: false };
  const r = raw as Record<string, unknown>;
  if (r.kind !== "voice") return { isV1: false };
  const vc = (r.voice as Record<string, unknown> | undefined)?.download_context as
    | Record<string, unknown>
    | undefined;
  if (!vc || typeof vc.msg_id !== "number") return { isV1: false };
  return {
    isV1: true,
    voiceCtx: {
      msgId: vc.msg_id,
      newMsgId: typeof vc.new_msg_id === "string" ? vc.new_msg_id : "",
      clientMsgId: typeof vc.client_msg_id === "string" ? vc.client_msg_id : "",
      masterBufId: typeof vc.master_buf_id === "string" ? vc.master_buf_id : "0",
      format: typeof vc.format === "number" ? vc.format : 4,
      length: typeof vc.length === "number" ? vc.length : 0,
      chatRoomName: typeof vc.chat_room_name === "string" ? vc.chat_room_name : undefined,
      fromUserName: typeof vc.from_user_name === "string" ? vc.from_user_name : undefined,
      toUserName: typeof vc.to_user_name === "string" ? vc.to_user_name : undefined,
    },
  };
}
/**
 * 用新版 DownloadVoiceBinary 下载语音 → STT 转写 + OSS。
 * v1.3.22 VENDOR-TRANSCRIPT: 优先用 vendor 自带 transcript (voice.transcript, wechat_official),
 *   免插件 STT (省 token + 快 + 准). 无 vendor transcript 才走 SiliconFlow STT。
 * 返回 { mediaUrl, mediaSize, filename: STT文字 } — handler 注入 content 让 AI 看到转写。
 */
export async function enrichVoiceMessageFromV1(
  ctx: WppAccountCtx,
  voiceCtx: V1VoiceDownloadCtx,
  vendorTranscript?: string,
): Promise<MediaEnrichResult> {
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  let sttText: string | null = null;
  // v1.3.22 VENDOR-TRANSCRIPT: vendor 已转写 (voice.transcript) → 直接用它, 不下载不 STT
  const vendorText = vendorTranscript?.trim();
  if (vendorText) {
    sttText = vendorText;
    log.info(`[WPP v1.3.22 VENDOR-TRANSCRIPT] use vendor transcript (wechat_official): "${vendorText.slice(0, 50)}"`);
    return { mediaUrl: null, mediaSize: null, filename: sttText };
  }
  try {
    const url = `${ctx.baseUrl.replace(/\/$/, "")}/api/Tools/DownloadVoiceBinary?authcode=${encodeURIComponent(ctx.authcode ?? "")}`;
    const buf = await safeFetchWithCap(
      url,
      {
        method: "POST",
        headers: { "Content-Type": "application/json", "TokenKey": ctx.tokenKey },
        body: JSON.stringify({
          msg_id: voiceCtx.msgId,
          new_msg_id: voiceCtx.newMsgId,
          client_msg_id: voiceCtx.clientMsgId,
          master_buf_id: voiceCtx.masterBufId,
          format: voiceCtx.format,
          length: voiceCtx.length,
          chat_room_name: voiceCtx.chatRoomName,
          from_user_name: voiceCtx.fromUserName,
          to_user_name: voiceCtx.toUserName,
        }),
        signal: AbortSignal.timeout(30_000),
      },
      20 * 1024 * 1024, // 20MB hard cap (silk 通常 <2MB)
    );
    if (buf.length === 0) {
      return { mediaUrl: null, mediaSize: null, error: "DownloadVoiceBinary empty" };
    }

    tmpPath = path.join(os.tmpdir(), `wpp-voice-v1-${crypto.randomBytes(6).toString("hex")}.silk`);
    fs.writeFileSync(tmpPath, buf);

    try {
      const sttR = await transcribeSilkBuffer(buf);
      if (sttR?.text) {
        sttText = sttR.text;
        log.info(`[WPP v1.2.6 VOICE-DOWNLOAD-BINARY] STT ok: "${sttText.slice(0, 50)}${sttText.length > 50 ? "..." : ""}"`);
      }
    } catch (e) {
      log.warn(`[WPP v1.2.6] voice STT failed (non-fatal): ${formatErr(e)}`);
    }

    const filename = `${crypto.randomBytes(8).toString("hex")}.silk`;
    const ossKey = buildOssKey(ctx.accountId, "voices", filename);
    const ossUrl = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.2.6 VOICE-DOWNLOAD-BINARY] ok: ${ossUrl} (${buf.length} bytes)`);
    return { mediaUrl: ossUrl, mediaSize: buf.length, ...(sttText ? { filename: sttText } : {}) };
  } catch (e) {
    log.warn(`[WPP v1.2.6 VOICE-DOWNLOAD-BINARY] failed: ${formatErr(e)}`);
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}

// src/storage/stt.ts - SiliconFlow SenseVoiceSmall STT
// Pipeline: silk → decode → PCM → WAV header → SiliconFlow API → text

import { warn, error } from "../core/logger.js";
import { decodeSilkToPcm } from "./silk.js";
import { safeFetch } from "../util/safe-fetch.js"; // v1.3.27 P3-safe-fetch: 白名单化防 SSRF (自定义 env URL 需自行加白名单)

const SILICONFLOW_STT_URL = process.env.SILICONFLOW_STT_URL || "https://api.siliconflow.cn/v1/audio/transcriptions";
const STT_MODEL = process.env.SILICONFLOW_STT_MODEL || "FunAudioLLM/SenseVoiceSmall";
const SILICONFLOW_API_KEY = process.env.SILICONFLOW_API_KEY || "";

const WAV_SAMPLE_RATE = 24_000;
const WAV_CHANNELS = 1;
const WAV_BITS_PER_SAMPLE = 16;

/** 纯函数: PCM → WAV (44 字节 RIFF/WAVE 头 + PCM 数据). 导出供测试 (v1.3.74 P2-2) */
export function buildWavBuffer(pcmBuffer: Buffer): Buffer {
  const pcmLen = pcmBuffer.length;
  const totalSize = 44 + pcmLen;
  const wav = Buffer.allocUnsafe(totalSize);
  wav.write("RIFF", 0);
  wav.writeUInt32LE(totalSize - 8, 4);
  wav.write("WAVE", 8);
  wav.write("fmt ", 12);
  wav.writeUInt32LE(16, 16);
  wav.writeUInt16LE(1, 20);
  wav.writeUInt16LE(WAV_CHANNELS, 22);
  wav.writeUInt32LE(WAV_SAMPLE_RATE, 24);
  wav.writeUInt32LE(WAV_SAMPLE_RATE * WAV_CHANNELS * (WAV_BITS_PER_SAMPLE / 8), 28);
  wav.writeUInt16LE(WAV_CHANNELS * (WAV_BITS_PER_SAMPLE / 8), 32);
  wav.writeUInt16LE(WAV_BITS_PER_SAMPLE, 34);
  wav.write("data", 36);
  wav.writeUInt32LE(pcmLen, 40);
  pcmBuffer.copy(wav, 44);
  return wav;
}

export interface TranscribeResult {
  text: string;
  durationMs: number;
}

/**
 * silk buffer → WAV → SiliconFlow STT → 转写文字 + 时长
 * 缺 apiKey / decode 失败 → return null (caller 决定 fallback)
 */
export async function transcribeSilkBuffer(
  silkBuffer: Buffer,
  apiKey: string = SILICONFLOW_API_KEY,
): Promise<TranscribeResult | null> {
  if (!apiKey) {
    warn("[STT] missing SILICONFLOW_API_KEY env var");
    return null;
  }

  let pcmBuffer: Buffer;
  try {
    pcmBuffer = await decodeSilkToPcm(silkBuffer);
  } catch (e) {
    warn(`[STT] silk decode failed: ${e instanceof Error ? e.message : String(e)}`);
    return null;
  }
  const wav = buildWavBuffer(pcmBuffer);

  const form = new FormData();
  form.append("file", new Blob([new Uint8Array(wav)], { type: "audio/wav" }), "voice.wav");
  form.append("model", STT_MODEL);
  form.append("response_format", "json");

  let response: Response | null = null;
  let lastError: string | null = null;
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      response = await safeFetch(SILICONFLOW_STT_URL, {
        method: "POST",
        headers: { Authorization: `Bearer ${apiKey}` },
        body: form,
        signal: AbortSignal.timeout(60_000), // 60s 单次超时
      });
      if (response.ok) break;
      const errText = await response.text().catch(() => "");
      const status = response.status;
      const isRetryable = status === 401 || status === 429 || status >= 500;
      if (isRetryable && attempt < 3) {
        warn(`[STT] SiliconFlow ${status} (attempt ${attempt}/3), retrying...`);
        await new Promise((r) => setTimeout(r, attempt * 1000));
        lastError = `HTTP ${status}: ${errText}`;
        continue;
      }
      error(`[STT] SiliconFlow API error ${status}: ${errText.slice(0, 200)}`);
      return null;
    } catch (e) {
      lastError = e instanceof Error ? e.message : String(e);
      if (attempt < 3) {
        warn(`[STT] fetch error (attempt ${attempt}/3): ${lastError}`);
        await new Promise((r) => setTimeout(r, attempt * 1000));
        continue;
      }
      error(`[STT] SiliconFlow fetch error after 3 retries: ${lastError}`);
      return null;
    }
  }
  if (!response || !response.ok) {
    error(`[STT] SiliconFlow failed: ${lastError}`);
    return null;
  }
  const data: { text?: string; transcript?: string } = await response.json();
  const text = data.text || data.transcript || "";
  if (!text) {
    warn("[STT] SiliconFlow returned empty text");
    return null;
  }
  return {
    text: String(text),
    durationMs: Math.round((pcmBuffer.length / (WAV_SAMPLE_RATE * 2)) * 1000),
  };
}

// src/storage/silk.ts - Silk 编解码 (从 gewe v3.1.6 fork, WPP 适配)
//
// 编码器/解码器路径:
//   - 编码: /root/silk_decoder/silk/encoder (MP3/PCM → silk for outbound 语音发送)
//   - 解码: /root/silk_decoder/silk/decoder (silk → PCM for STT)
//
// 仿 gewe src/storage/silk.ts 86 行, 但 WPP 简化:
//   - 不引 env config (WPP 用 accounts/<id>.json 配置, demo 阶段先用 default)
//   - 不接 OSS 音频后端 (WPP 暂无)
//   - mkdtemp + try/finally 范式 (gewe 11 处已确认安全)

import { execAsync } from "../util/exec.js";
import { unlinkSync, mkdtempSync, rmdirSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import { join } from "node:path";
import os from "node:os";

// v1.3.19 RELEASE: silk 二进制路径可经 env 覆盖 (接收方可能装在不同位置)
//   生产不设 env → 默认 /root/silk_decoder/ (行为不变)
const DEFAULT_SILK_ENCODER_PATH = process.env.WPP_SILK_ENCODER_PATH || "/root/silk_decoder/silk/encoder";
const DEFAULT_SILK_DECODER_PATH = process.env.WPP_SILK_DECODER_PATH || "/root/silk_decoder/silk/decoder";

export interface SilkDecodeResult {
  buffer: Buffer;
  contentType: string;
  fileName: string;
}

/**
 * 解码 silk → PCM
 * @param silkBuffer 输入 silk 二进制
 * @param outputPath 输出路径 (可选, 默认临时文件)
 * @param decoderPath 自定义 decoder 路径 (可选)
 */
export async function decodeSilkToPcm(
  silkBuffer: Buffer,
  outputPath?: string,
  decoderPath?: string,
): Promise<Buffer> {
  const tmpDir = mkdtempSync(join(os.tmpdir(), "wpp-silk-"));
  const silkPath = join(tmpDir, "voice.silk");
  const pcmPath = outputPath ?? join(tmpDir, "voice.pcm");

  try {
    await writeFile(silkPath, silkBuffer);

    const decoder = decoderPath ?? DEFAULT_SILK_DECODER_PATH;
    // 10s timeout 防 native binary hang
    await execAsync(decoder, [silkPath, pcmPath], { timeoutMs: 10_000 });
    return await readFile(pcmPath);
  } finally {
    try { unlinkSync(silkPath); } catch { /* ignore */ }
    if (!outputPath) {
      try { rmdirSync(tmpDir); } catch { /* ignore */ }
    }
  }
}

/**
 * 编码 PCM → silk (出站语音消息用, sendVoice pipeline)
 */
export async function encodePcmToSilk(
  pcmBuffer: Buffer,
  outputPath?: string,
  encoderPath?: string,
): Promise<Buffer> {
  const tmpDir = mkdtempSync(join(os.tmpdir(), "wpp-silk-enc-"));
  const pcmPath = join(tmpDir, "voice.pcm");
  const silkPath = outputPath ?? join(tmpDir, "voice.silk");

  try {
    await writeFile(pcmPath, pcmBuffer);
    const encoder = encoderPath ?? DEFAULT_SILK_ENCODER_PATH;
    await execAsync(encoder, [pcmPath, silkPath], { timeoutMs: 10_000 });
    return await readFile(silkPath);
  } finally {
    try { unlinkSync(pcmPath); } catch { /* ignore */ }
    if (!outputPath) {
      try { rmdirSync(tmpDir); } catch { /* ignore */ }
    }
  }
}

// src/inbound/media-enrich/video.ts - 视频消息 enrich (v0 XML + v1 download_context 分片)
// 从 media-enrich.ts v1.3.26 拆分 (2026-08-10, P3-2): 仅搬运, 不优化

import { logObj as log, formatErr } from "../../core/logger.js";
import { parseVideoXml } from "./xml.js";
import { loadOssConfig, uploadToOss, downloadByEndpoint, buildOssKey } from "./shared.js";
import type { MediaEnrichResult } from "./shared.js";
import type { WppAccountCtx } from "../../send/factory.js";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";

/** 视频消息 (msgType=43) 下载 + OSS */
export async function enrichVideoMessage(
  ctx: WppAccountCtx,
  xml: string,
): Promise<MediaEnrichResult> {
  const parsed = parseVideoXml(xml);
  if (!parsed) return { mediaUrl: null, mediaSize: null, error: "no aeskey/fileNo in xml" };
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  try {
    // vendor 端点无 Cdn 前缀 (错调 /Tools/CdnDownloadVideo 会 404)
    const b64 = await downloadByEndpoint(ctx, "/Tools/DownloadVideo", parsed.aesKey, parsed.fileNo);
    const buf = Buffer.from(b64, "base64");
    const ext = parsed.md5 ? "mp4" : "mp4";
    tmpPath = path.join(os.tmpdir(), `wpp-vid-${crypto.randomBytes(6).toString("hex")}.${ext}`);
    fs.writeFileSync(tmpPath, buf);
    const filename = `${parsed.md5 ?? crypto.randomBytes(8).toString("hex")}.mp4`;
    const ossKey = buildOssKey(ctx.accountId, "videos", filename);
    const url = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.3.74] video enrich OSS: ${url} (${buf.length} bytes)`);
    return { mediaUrl: url, mediaSize: buf.length };
  } catch (e) {
    log.warn(`[WPP v1.3.74] video enrich failed: ${formatErr(e)}`, { aesKey: parsed.aesKey });
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
/**
 * v1.3.8 VIDEO-DOWNLOAD: 新版 vendor (8/10) 视频推送带 video.download_context,
 * 提交给 /Tools/DownloadVideo → 视频分片 → OSS 上传 → 公网 URL。
 * 结构: { msg_id, data_len, section:{start_pos,data_len}, to_wxid }
 */
export interface V1VideoDownloadCtx {
  msgId: number;
  dataLen: number;
  toWxid: string;
  compressType?: number;
}
/** 从 raw_payload 提取新版视频 download_context (kind=video + video.download_context) */
export function isV1SchemaVideo(raw: unknown): { isV1: boolean; videoCtx?: V1VideoDownloadCtx } {
  if (!raw || typeof raw !== "object") return { isV1: false };
  const r = raw as Record<string, unknown>;
  if (r.kind !== "video") return { isV1: false };
  const vc = (r.video as Record<string, unknown> | undefined)?.download_context as
    | Record<string, unknown>
    | undefined;
  if (!vc || typeof vc.msg_id !== "number") return { isV1: false };
  return {
    isV1: true,
    videoCtx: {
      msgId: vc.msg_id,
      dataLen: typeof vc.data_len === "number" ? vc.data_len : 0,
      toWxid: typeof vc.to_wxid === "string" ? vc.to_wxid : "",
      compressType: typeof vc.compress_type === "number" ? vc.compress_type : 0,
    },
  };
}
/** 用新版 DownloadVideo 下载视频 → OSS。失败返回 error (调用方降级)。 */
export async function enrichVideoMessageFromV1(
  ctx: WppAccountCtx,
  videoCtx: V1VideoDownloadCtx,
): Promise<MediaEnrichResult> {
  const oss = loadOssConfig();
  if (!oss) return { mediaUrl: null, mediaSize: null, error: "oss credentials missing" };
  let tmpPath: string | null = null;
  try {
    const url = `${ctx.baseUrl.replace(/\/$/, "")}/api/Tools/DownloadVideo?authcode=${encodeURIComponent(ctx.authcode ?? "")}`;
    const chunks: Buffer[] = [];
    let totalLen = videoCtx.dataLen;
    let startPos = 0;
    const CHUNK = 1048576; // 1MB 每段 (与 download_context.section 一致)
    while (startPos < totalLen) {
      const sectionLen = Math.min(CHUNK, totalLen - startPos);
      // 单段 1MB < 200MB cap → 用普通 safeFetch (这段走 host 白名单 + 协议校验就够)
      const safeMod = await import("../../util/safe-fetch.js");
      const resp = await safeMod.safeFetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json", "TokenKey": ctx.tokenKey },
        body: JSON.stringify({
          to_wxid: videoCtx.toWxid,
          msg_id: videoCtx.msgId,
          data_len: totalLen,
          section: { start_pos: startPos, data_len: sectionLen },
          compress_type: videoCtx.compressType,
        }),
        signal: AbortSignal.timeout(30_000),
      });
      if (!resp.ok) {
        const errText = await resp.text().catch(() => "");
        return { mediaUrl: null, mediaSize: null, error: `DownloadVideo HTTP ${resp.status}: ${errText.slice(0, 200)}` };
      }
      const json = (await resp.json()) as {
        Data?: { totalLen?: number; data?: { buffer?: string }; Video?: string };
      };
      const data = json.Data ?? {};
      if (typeof data.totalLen === "number") totalLen = data.totalLen;
      const b64 = data.data?.buffer ?? data.Video ?? "";
      if (!b64) {
        return { mediaUrl: null, mediaSize: null, error: `DownloadVideo chunk ${startPos} no buffer` };
      }
      const chunk = Buffer.from(b64, "base64");
      if (chunk.length === 0) {
        return { mediaUrl: null, mediaSize: null, error: `DownloadVideo chunk ${startPos} empty` };
      }
      chunks.push(chunk);
      startPos += chunk.length;
      // 终止条件: 已拉到 totalLen (不要用 chunk.length < sectionLen — 每段固定 61440, 会提前 break)
      if (startPos >= totalLen) break;
      if (chunk.length === 0) break; // 无进展
      //   但若段 < 1MB (vendor 异常), 200 段其实只防 ~50MB; 改成按 totalBytes 严格 200MB)
      const totalBytes = chunks.reduce((s, c) => s + c.length, 0);
      const MAX_VIDEO_BYTES = 200 * 1024 * 1024;
      if (totalBytes > MAX_VIDEO_BYTES) {
        return { mediaUrl: null, mediaSize: null, error: `video chunks exceeded ${MAX_VIDEO_BYTES} bytes` };
      }
    }
    const buf = Buffer.concat(chunks);
    if (buf.length === 0) {
      return { mediaUrl: null, mediaSize: null, error: "DownloadVideo empty" };
    }
    tmpPath = path.join(os.tmpdir(), `wpp-video-v1-${crypto.randomBytes(6).toString("hex")}.mp4`);
    fs.writeFileSync(tmpPath, buf);
    const filename = `${crypto.randomBytes(8).toString("hex")}.mp4`;
    const ossKey = buildOssKey(ctx.accountId, "videos", filename);
    const ossUrl = await uploadToOss(oss, tmpPath, ossKey);
    log.info(`[WPP v1.3.8 VIDEO-DOWNLOAD] ok: ${ossUrl} (${buf.length} bytes)`);
    return { mediaUrl: ossUrl, mediaSize: buf.length };
  } catch (e) {
    log.warn(`[WPP v1.3.8 VIDEO-DOWNLOAD] failed: ${formatErr(e)}`);
    return { mediaUrl: null, mediaSize: null, error: (e as Error).message };
  } finally {
    if (tmpPath) try { fs.unlinkSync(tmpPath); } catch { /* ignore */ }
  }
}
